async function loadAll(){
 if(!LIVE){const d=demo.load(),r=ME.role;DB={profiles:d.profiles};T.forEach(t=>DB[t]=d[t].filter(x=>r=="admin"||(r=="coach"&&x.coach_id==ME.id)));if(r=="coach"){const my=d.students.filter(s=>s.coach_id==ME.id).map(s=>s.id);["fees","invoices"].forEach(t=>DB[t]=d[t].filter(x=>my.includes(x.student_id)))}
  if(r=="student"||r=="parent"){const m=d.students.filter(s=>r=="student"?s.student_email==ME.email:s.parent_email==ME.email),ids=m.map(s=>s.id),bs=m.map(s=>s.batch_id);
   DB.students=m;DB.batches=d.batches.filter(b=>bs.includes(b.id));DB.classes=d.classes.filter(c=>bs.includes(c.batch_id));["attendance","fees","messages","invoices"].forEach(t=>DB[t]=d[t].filter(x=>ids.includes(x.student_id)))}return}
 DB={};for(const t of [...T,"profiles"]){const{data}=await sb.from(t).select("*");DB[t]=data||[]}}
async function add(t,row,skip){row.id=uid();if(ME.role=="coach")row.coach_id=ME.id;
 if(!LIVE){const d=demo.load();d[t].push(row);demo.save(d)}else{delete row.id;const{error}=await sb.from(t).insert(row);if(error)alert(error.message)}await log("Added",t,row.name||row.title||row.kind||"");if(!skip)await go()}
