function authView(msg=""){root.innerHTML=`<div class="auth"><div class="box"><img src="assets/logo-header.png" alt="MyChess64 Academy"><h2>${JOIN?"Join the Academy as a "+JOIN[0].toUpperCase()+JOIN.slice(1):"Welcome to the Academy"}</h2><p style="color:var(--mu)">${LIVE?"Log in or create your account.":"<b>Demo mode</b> (data stays in this browser). Pick a role."}</p><p class="bad">${msg}</p>
${LIVE?`<input id="nm" placeholder="Full name (sign up only)"><input id="em" type="email" placeholder="Email"><input id="pw" type="password" placeholder="Password (min 6)"><select id="rl"><option value="student" ${JOIN=="student"?"selected":""}>I am a Student</option><option value="parent">I am a Parent</option><option value="coach" ${JOIN=="coach"?"selected":""}>I am a Coach (needs approval)</option></select><div class="row"><button class="btn" onclick="login()">Log in</button><button class="btn or" onclick="signup()">Sign up</button></div>`:
["admin|a1|Admin","coach|c1|Coach (Coach Demo)","coach|c2|Coach B (see isolation)","student|x|Student","parent|y|Parent"].map(x=>{const[r,i,l]=x.split("|");return`<button class="btn g" style="width:100%;margin:4px 0" onclick="demoLogin('${r}','${i}')">Enter as ${l}</button>`}).join("")}<p style="text-align:center;margin:14px 0 0"><a href="index.html" class="back">← Back to Academy home</a></p><p class="cr">${BRAND.credit}</p></div></div>`}
function demoLogin(role,id){const p=demo.load().profiles.find(x=>x.id==id);ME=p?{...p}:{id,name:role=="student"?"Aarav":"Aarav's Parent",role,approved:true};ME.email=role=="student"?"student@demo":"parent@demo";TAB="Dashboard";go()}
async function login(){const{error}=await sb.auth.signInWithPassword({email:$("#em").value,password:$("#pw").value});error?authView(error.message):boot()}
async function signup(){const{error}=await sb.auth.signUp({email:$("#em").value,password:$("#pw").value,options:{data:{name:$("#nm").value,role:$("#rl").value}}});error?authView(error.message):authView("Account created. Confirm email if asked, then log in.")}
async function logout(){if(LIVE)await sb.auth.signOut();ME=null;authView()}
async function boot(){if(!LIVE)return authView();const{data:{session}}=await sb.auth.getSession();if(!session)return authView();const{data:p}=await sb.from("profiles").select("*").eq("id",session.user.id).single();ME={...p,email:session.user.email};go()}
