 due=sum(DB.students,s=>fd(s)),mon=sum(DB.fees.filter(f=>(f.paid_on||"").startsWith(monthKey())),f=>f.amount),wk=DB.classes.filter(c=>c.day>=today()).length,done=DB.classes.filter(c=>c.status=="completed").length;
