let FL={};
const fd=s=>Math.max(0,(FL[s.id]||{}).bal||0);
function computeFees(){FL={};DB.students.forEach(s=>{const inv=DB.invoices.filter(i=>i.student_id==s.id).sort((a,b)=>(a.due_date||"9").localeCompare(b.due_date||"9")||(a.created_at||"").localeCompare(b.created_at||"")),
 pays=DB.fees.filter(f=>f.student_id==s.id),paid=sum(pays,f=>f.amount);let pool=paid,billed=0;
 const rows=inv.map(i=>{const a=+i.amount||0;billed+=a;const p=Math.min(a,pool);pool-=p;const bal=a-p;return{...i,paid:p,bal,status:bal<=0?"Paid":i.due_date&&i.due_date<today()?"Overdue":p>0?"Partial":"Unpaid"}});
 const bal=billed-paid,od=sum(rows.filter(r=>r.status=="Overdue"),r=>r.bal);
 FL[s.id]={inv:rows,pays,billed,paid,bal,overdue:od,status:!billed?"No fees":bal<=0?"Paid":od>0?"Overdue":paid>0?"Partial":"Unpaid"}})}
const fb=s=>`<span style="font-weight:600;color:${{Paid:"#16a34a",Overdue:"#dc2626",Partial:"#d98a0a",Unpaid:"#7c3aed"}[s]||"#64718a"}">${s}</span>`;
const xbr=(t,id,sid)=>`<button class="btn g sm" onclick="delRec('${t}','${id}','${sid}')">Delete</button>`;
async function delRec(t,id,sid){await del(t,id);showLedger(sid)}
function showLedger(sid){document.querySelector(".mdl")?.remove();const s=DB.students.find(x=>x.id==sid);if(!s)return;const d=document.createElement("div");d.className="mdl";
 d.innerHTML=`<div class="mb"><div class="top"><h2 style="margin:0;font-size:18px">Fee history · ${esc(s.name)} ${fb(FL[sid].status)}</h2><button class="btn g sm" onclick="this.closest('.mdl').remove()">Close ✕</button></div>${ledgerHTML(sid,ME.role=="admin")}</div>`;document.body.appendChild(d)}
function printReceipt(id){const p=DB.fees.find(x=>x.id==id),s=p&&DB.students.find(x=>x.id==p.student_id);if(!s)return;const f=FL[s.id],w=window.open("","_blank");if(!w)return alert("Please allow pop-ups to print");
 w.document.write(`<title>Receipt ${esc(p.receipt_no||"")}</title><body style="font-family:Poppins,Arial,sans-serif;max-width:560px;margin:30px auto;border:2px solid #12305a;border-radius:14px;padding:24px"><img src="${BRAND.logo}" style="height:44px" alt="MyChess64 Academy"><br><small>Payment Receipt</small><hr><p>Receipt No: <b>${esc(p.receipt_no||"-")}</b><br>Date: <b>${p.paid_on||"-"}</b><br>Student: <b>${esc(s.name)}</b><br>Coach: ${esc(cName(s.coach_id))}<br>Mode: ${esc(p.method||"-")}${p.note?"<br>Note: "+esc(p.note):""}</p><h1 style="color:#16a34a;margin:6px 0">${money(p.amount)}</h1><p>Total billed ${money(f.billed)} · Total paid ${money(f.paid)} · Balance ${money(Math.max(0,f.bal))}</p><hr><small>Computer-generated receipt. Thank you!<br>${BRAND.credit}</small><script>onload=()=>print()<\/script></body>`);w.document.close()}
