const DOCCSS=".hd img{height:46px}body{font-family:Poppins,Arial,sans-serif;max-width:820px;margin:24px auto;color:#14213a;padding:0 16px}h1{margin:0;color:#12305a;font-size:22px}h3{margin:16px 0 4px;color:#12305a}.hd{display:flex;justify-content:space-between;align-items:flex-end;border-bottom:3px solid #f9a826;padding-bottom:10px;margin-bottom:14px}.box{display:flex;gap:10px;margin:12px 0}.box div{flex:1;border:1px solid #d5dbe6;border-radius:10px;padding:10px}.box b{display:block;font-size:20px}table{width:100%;border-collapse:collapse;margin:6px 0 14px}td,th{border-bottom:1px solid #e4e7ee;padding:7px;text-align:left;font-size:13px}th{background:#f2f5fa}small{color:#64718a}";
const docWrap=(title,sub,body)=>`<!doctype html><meta charset="utf-8"><title>${title}</title><style>${DOCCSS}.sumg{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px;margin-bottom:14px}.tile{border-radius:16px;padding:16px 18px;color:#fff;box-shadow:0 8px 20px #0003}.tile small{display:block;color:#ffffffcc;font-size:12px;font-weight:600}.tile b{display:block;font-size:28px;margin-top:2px}.prog{height:8px;border-radius:6px;background:#ffffff40;margin-top:8px}.prog i{display:block;height:100%;border-radius:6px;background:#fff}.tabs{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px}.tabs button{background:#ffffff14;color:#cfd9ea;border:0;border-radius:99px;padding:8px 16px;cursor:pointer;font-weight:600}.tabs .on{background:var(--or);color:#1a1203}.tb{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:10px 0}.tb>*{flex:0 0 auto}.tb select{width:auto;margin:0}.mb .tile b{font-size:24px}</style><div class="hd"><div><img src="${BRAND.logo}" alt="MyChess64 Academy"><br><small>${sub}</small></div><div style="text-align:right"><b>${title}</b><br><small>Generated ${today()}</small></div></div>${body}<p><small>Computer-generated statement. For any query, please contact the Academy.<br>${BRAND.credit}</small></p>`;
