function stmt(sid){const f=FL[sid];let run=0;return[...f.inv.map(i=>({d:i.due_date||(i.created_at||"").slice(0,10),k:0,txt:"Fee: "+(i.description||""),dr:+i.amount,cr:0})),...f.pays.map(p=>({d:p.paid_on||"",k:1,id:p.id,txt:"Payment received"+(p.method?" ("+p.method+")":"")+(p.receipt_no?" · "+p.receipt_no:"")+(p.note?" · "+p.note:""),dr:0,cr:+p.amount}))].sort((a,b)=>a.d.localeCompare(b.d)||a.k-b.k).map(e=>(run+=e.dr-e.cr,{...e,run}))}
