/* --- coach payout engine --- */
function earn(cid,m){const c=DB.profiles.find(p=>p.id==cid)||{},rate=+c.pay_rate||0,mode=c.pay_mode||"percent",by={};DB.fees.filter(f=>f.coach_id==cid&&mk(f.paid_on)==m).forEach(f=>by[f.student_id]=(by[f.student_id]||0)+ +f.amount);
 const srows=Object.entries(by).map(([id,a])=>({id,collected:a,share:mode=="percent"?Math.round(a*rate)/100:0})),cl=DB.classes.filter(k=>k.coach_id==cid&&k.status=="completed"&&mk(k.day)==m).sort((a,b)=>a.day.localeCompare(b.day)).map(k=>({...k,amt:mode=="class"?rate:0}));
 return{mode,rate,srows,cl,collected:sum(srows,r=>r.collected),note:c.pay_note||"",from:c.pay_from||"",total:mode=="percent"?sum(srows,r=>r.share):mode=="class"?sum(cl,r=>r.amt):(!c.pay_from||m>=c.pay_from?rate:0)}}
const paidOut=(cid,m)=>sum(DB.payouts.filter(p=>p.coach_id==cid&&(!m||p.month==m)),p=>p.amount);
const basis=e=>e.mode=="percent"?e.rate+"% of fees collected from the coach's students":e.mode=="class"?money(e.rate)+" per completed class":money(e.rate)+" fixed payment per month"+(e.from?" (from "+monthName(e.from)+")":"");
const unitOf=m=>m=="class"?"₹ per class":m=="month"?"₹ per month":"% of fees";const ruleHint=id=>{$("#pu_"+id).textContent=unitOf($("#pmd_"+id).value)};
function coachMonths(cid,extra){const c=DB.profiles.find(p=>p.id==cid)||{},s=new Set([today().slice(0,7),extra]);DB.fees.filter(f=>f.coach_id==cid).forEach(f=>s.add(mk(f.paid_on)));DB.classes.filter(k=>k.coach_id==cid&&k.status=="completed").forEach(k=>s.add(mk(k.day)));DB.payouts.filter(p=>p.coach_id==cid).forEach(p=>s.add(p.month));if(c.pay_mode=="month"&&c.pay_from)s.add(c.pay_from);
 const a=[...s].filter(Boolean).sort(),out=[];let[y,mo]=a[0].split("-").map(Number);const end=a[a.length-1];for(let n=0;n<240;n++){const k=y+"-"+String(mo).padStart(2,"0");out.push(k);if(k>=end)break;if(++mo>12){mo=1;y++}}return out}
function coachLedger(cid){let run=0;return coachMonths(cid).map(m=>{const e=earn(cid,m).total,p=paidOut(cid,m);run+=e-p;return{m,e,p,bal:e-p,run}})}
const cTot=cid=>{const L=coachLedger(cid);return{e:sum(L,r=>r.e),p:sum(L,r=>r.p)}};
const stRows=e=>e.srows.map(r=>[esc(sName(r.id)),money(r.collected),e.mode=="percent"?money(r.share):"-"]),clRows=e=>e.cl.map(k=>[k.day,esc(k.title),esc(bName(k.batch_id)),e.mode=="class"?money(k.amt):"-"]);
