function coachLedgerDoc(cid){const L=coachLedger(cid),t=cTot(cid);return docWrap("Coach Payout Ledger","Coach: <b>"+esc(cName(cid))+"</b>",sumBox(t.e,t.p,Math.max(0,t.e-t.p),["Total Earned","Total Paid","Payable Balance"])+tbl(["Month","Earned","Paid","Balance","Cumulative payable"],L.map(r=>[monthName(r.m),money(r.e),money(r.p),money(r.bal),money(r.run)])))}
